meta.script:
{
  "@context": "https://schema.org",
  "@type": "NewsArticle",
  "headline": "نرخی نەوت 6٪ بەرزبووەوە و گەیشتە 107 دۆلار بۆ هەر بەرمیلێک",
  "image": ["https://reedmediatv.github.io/news-3.jpg"],
  "datePublished": "2026-09-11T10:40:00+03:00",
  "author": [{ "@type": "Organization", "name": "Reed Media", "url": "https://reedmediatv.github.io" }],
  "publisher": { "@type": "Organization", "name": "Reed Media", "logo": { "@type": "ImageObject", "url": "https://reedmediatv.github.io/news-3.jpg" } }
}

body.script:
const translations = {
    ku: { title_tag: "نرخی نەوت بەرزبووەوە - Reed Media", live_badge: "پەخشی ڕاستەوخۆ", logo_sub: "میدیای سوور", slogan: "ڕۆژنامەگەری سەربەخۆ و خێرا", nav_home: "سەرەکی", nav_breaking: "بەپەلە", nav_kurdistan: "کوردستان", nav_world: "جیهان", nav_economy: "ئابووری", nav_archive: "ئەرشیف", footer_text: "هەموو مافەکانی پارێزراوە بۆ © Reed Media 2026", post_time_label: "کاتی بڵاوکردنەوە:", back_btn: "گەڕانەوە بۆ سەرەکی", article_cat: "ئابووری • بازاڕەکان", article_title: "نرخی نەوت 6٪ بەرزبووەوە و گەیشتە 107 دۆلار بۆ هەر بەرمیلێک", para_1: "لەگەڵ کردنەوەی بازاڕەکانی جیهاندا بۆ ئەمڕۆ، نرخی نەوتی خاو بە ڕێژەی 6٪ بەرزبووەوە.", para_2: "نرخی نەوت گەیشتە 107 دۆلاری ئەمریکی، کە کاریگەری لەسەر بازاڕەکان دەبێت." },
    en: { title_tag: "Oil Prices Surge - Reed Media", live_badge: "LIVE BROADCAST", logo_sub: "Red Media", slogan: "Independent & Fast Journalism", nav_home: "Home", nav_breaking: "Breaking", nav_kurdistan: "Kurdistan", nav_world: "World", nav_economy: "Economy", nav_archive: "Archive", footer_text: "All rights reserved © Reed Media 2026", post_time_label: "Published Time:", back_btn: "Back to Home", article_cat: "Economy • Markets", article_title: "Oil prices jump 6% reaching $107 per barrel", para_1: "As global markets opened today, the price of crude oil witnessed a jump.", para_2: "According to the latest statistics, oil reached $107 USD." },
    ar: { title_tag: "ارتفاع أسعار النفط - ريد ميديا", live_badge: "بث مباشر", logo_sub: "الإعلام الأحمر", slogan: "صحافة مستقلة وسريعة", nav_home: "الرئيسية", nav_breaking: "عاجل", nav_kurdistan: "كردستان", nav_world: "عالم", nav_economy: "اقتصاد", nav_archive: "الأرشيف", footer_text: "جميع الحقوق محفوظة لـ © ريد ميديا 2026", post_time_label: "وقت النشر:", back_btn: "العودة للرئيسية", article_cat: "اقتصاد • الأسواق", article_title: "أسعار النفط تقفز 6% وتصل إلى 107 دولارات للبرميل", para_1: "مع افتتاح الأسواق العالمية اليوم، شهد سعر برميل النفط قفزة كبيرة.", para_2: "وصل سعر النفط إلى 107 دولارات أمريكية." }
};

function setLang(lang) {
    document.documentElement.lang = (lang === 'ku' ? 'ckb' : lang);
    document.documentElement.dir = (lang === 'en' ? 'ltr' : 'rtl');
    document.querySelectorAll('[data-key]').forEach(el => {
        const key = el.getAttribute('data-key');
        if (translations[lang] && translations[lang][key]) el.textContent = translations[lang][key];
    });
    document.querySelectorAll('.lang-btn').forEach(btn => btn.classList.remove('active'));
    if(document.getElementById('btn-' + lang)) document.getElementById('btn-' + lang).classList.add('active');
    localStorage.setItem('reed_lang', lang);
    updateSmartFeatures(lang);
}

function updateSmartFeatures(lang) {
    document.querySelectorAll("time[datetime]").forEach(el => {
        const diff = Math.floor((new Date() - new Date(el.getAttribute("datetime"))) / 1000); 
        if (lang === 'en') {
            if (diff < 60) el.textContent = "Just now"; else if (diff < 3600) el.textContent = `${Math.floor(diff/60)}m ago`; else if (diff < 86400) el.textContent = `${Math.floor(diff/3600)}h ago`; else el.textContent = `${Math.floor(diff/86400)}d ago`;
        } else if (lang === 'ar') {
            if (diff < 60) el.textContent = "الآن"; else if (diff < 3600) el.textContent = `منذ ${Math.floor(diff/60)} دقيقة`; else if (diff < 86400) el.textContent = `منذ ${Math.floor(diff/3600)} ساعة`; else el.textContent = `منذ ${Math.floor(diff/86400)} يوم`;
        } else {
            if (diff < 60) el.textContent = "ئێستا"; else if (diff < 3600) el.textContent = `پێش ${Math.floor(diff/60)} خولەک`; else if (diff < 86400) el.textContent = `پێش ${Math.floor(diff/3600)} کاتژمێر`; else el.textContent = `پێش ${Math.floor(diff/86400)} ڕۆژ`;
        }
    });
}

window.addEventListener('DOMContentLoaded', () => {
    setLang(localStorage.getItem('reed_lang') || 'ku');

    const postId = "post-3";
    const pubDate = new Date("2026-09-11T10:40:00+03:00");
    const baseViews = 135;
    const rate = 2.2; 

    const minutes = Math.max(0, Math.floor((new Date() - pubDate) / 60000));
    let totalViews = baseViews + Math.floor(minutes * rate);

    if (!localStorage.getItem('view_' + postId)) {
        localStorage.setItem('view_' + postId, 'true'); 
        totalViews += 1; 
    } else {
        totalViews += 1; 
    }

    document.getElementById('post-view-count').textContent = totalViews.toLocaleString('en-US');
});
